// Inspired by abstract noise-based shaders
// Copyright Karan, 2025 - Educational shader example

const mat2 m2 = mat2(0.85, 0.52, -0.52, 0.85);

float hash(vec2 p) {
    return fract(sin(dot(p, vec2(127.1, 311.7))) * 43758.5453);
}

float noise(vec2 p) {
    vec2 i = floor(p);
    vec2 f = fract(p);
    f = f * f * (3.0 - 2.0 * f);
    return mix(mix(hash(i + vec2(0.0, 0.0)), hash(i + vec2(1.0, 0.0)), f.x),
               mix(hash(i + vec2(0.0, 1.0)), hash(i + vec2(1.0, 1.0)), f.x),
               f.y);
}

float fbm(vec2 p) {
    float f = 0.0;
    f += 0.5 * noise(p); p = m2 * p * 2.1;
    f += 0.25 * noise(p); p = m2 * p * 2.2;
    f += 0.125 * noise(p); p = m2 * p * 2.3;
    return f / 0.875;
}

float warpedNoise(vec2 p) {
    p += 0.1 * sin(vec2(0.21, 0.17) * iTime + length(p) * vec2(3.7, 3.1));
    return fbm(p);
}

void mainImage(out vec4 fragColor, in vec2 fragCoord) {
    vec2 p = (fragCoord.xy - iResolution.xy * 0.5) / iResolution.y;

    float n = warpedNoise(p * 2.0);

    vec3 baseColor = vec3(0.15, 0.1, 0.25) + 0.5 * vec3(0.3, 0.05, 0.45) * n;

    baseColor = mix(baseColor, vec3(0.9, 0.8, 0.7), 0.5 * n * n);
    baseColor = mix(baseColor, vec3(0.0, 0.3, 0.5), smoothstep(0.6, 1.0, abs(n)));
    baseColor *= 1.5 * vec3(0.8, 0.9, 1.0);

    fragColor = vec4(clamp(baseColor, 0.0, 1.0), 1.0);
}
